package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {









    @Test
    public void testIsNumber_Exponent() {
        assertTrue(NumberUtils.isNumber("123e456"));
        assertTrue(NumberUtils.isNumber("123E456"));
        assertTrue(NumberUtils.isNumber("123e+456"));
        assertTrue(NumberUtils.isNumber("123e-456"));
        assertTrue(NumberUtils.isNumber("123.456e10"));
        assertFalse(NumberUtils.isNumber("e123")); // No digit before E
        assertFalse(NumberUtils.isNumber("123e")); // Ends with E
        assertFalse(NumberUtils.isNumber("123e+")); // Ends with sign
        assertFalse(NumberUtils.isNumber("123e1.2")); // Dec in exponent
        assertFalse(NumberUtils.isNumber("123e1e2")); // Double E
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F
        assertTrue(NumberUtils.isNumber("123d"));
        assertTrue(NumberUtils.isNumber("123D"));
        assertTrue(NumberUtils.isNumber("123f"));
        assertTrue(NumberUtils.isNumber("123F"));
        assertTrue(NumberUtils.isNumber("123.45f"));
        // Note: The logic for d/D/f/F requires foundDigit and !allowSigns
        // It seems to allow them as the last character after a loop

        // l, L
        assertTrue(NumberUtils.isNumber("123l"));
        assertTrue(NumberUtils.isNumber("123L"));
        // But NOT with exponent or decimal point per the code logic: 
        // return foundDigit && !hasExp && !hasDecPoint;
        assertFalse(NumberUtils.isNumber("123.45l"));
        assertFalse(NumberUtils.isNumber("123e1l"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {













    @Test
    public void testIsNumber_EdgeCases() {
        // Test sign logic at start
        assertTrue(NumberUtils.isNumber("-5"));

        // Test the specific branch for trailing decimals
        assertTrue(NumberUtils.isNumber("123."));
        assertFalse(NumberUtils.isNumber(".")); // foundDigit would be false

        // Test the specific branch for type qualifiers at the end
        assertTrue(NumberUtils.isNumber("123f"));

        // Test combinations that should fail
        assertFalse(NumberUtils.isNumber("123e+"));
        assertFalse(NumberUtils.isNumber("123.4.5"));
        assertFalse(NumberUtils.isNumber("123e1.2"));

        // Test the manual check for last character
        assertTrue(NumberUtils.isNumber("123"));
        assertFalse(NumberUtils.isNumber("123z"));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen2Test {















    @Test
    public void testIsNumber_ComplexCombinations() {
        assertTrue(NumberUtils.isNumber("-123.456e-78"));
        assertTrue(NumberUtils.isNumber("+123.456E78"));
        assertFalse(NumberUtils.isNumber("123.456e-78.9"));
        assertFalse(NumberUtils.isNumber("123.456e-78f")); // f is not allowed after exponent per code logic (it checks i < chars.length)
    }
}
